package ucs03_zkgm

func assertIsRlmCurrent(_ int, rlm realm) {
	if !rlm.IsCurrent() {
		panic(errSpoofedRealm)
	}
}

package ucs03_zkgm

import (
	"encoding/hex"

	types "gno.land/p/onbloc/ibc/union/types"

	u256 "gno.land/p/onbloc/math/uint256"
)

// Precision invariant: channel balances are local vault precision (real custody), not wire precision.

// ChannelBalanceKeyV2 returns the storage key for a v2 channel balance entry.
func ChannelBalanceKeyV2(channelId types.ChannelId, path *u256.Uint, baseToken, quoteToken []byte) string {
	return channelId.String() + "/" + path.ToString() + "/" + hex.EncodeToString(baseToken) + "/" + hex.EncodeToString(quoteToken)
}

// decreaseChannelBalanceV2 subtracts from the escrow balance, erroring on underflow.
func (v *ucs03ZkgmV2LockedRecovery) decreaseChannelBalanceV2(_ int, rlm realm, channelId types.ChannelId, path *u256.Uint, baseToken, quoteToken []byte, amount int64) error {
	key := ChannelBalanceKeyV2(channelId, path, baseToken, quoteToken)

	amountUint256 := u256.NewUint(uint64(amount))

	curAmount, ok := v.store.GetChannelBalanceV2(key)
	if !ok || curAmount == nil || curAmount.Cmp(amountUint256) < 0 {
		return makeError(errChannelBalanceUnderflow)
	}

	calculatedAmount, underflow := u256.Zero().SubOverflow(curAmount, amountUint256)
	if underflow {
		return makeError(errChannelBalanceUnderflow)
	}

	v.store.SetChannelBalanceV2(0, rlm, key, calculatedAmount)

	return nil
}

package ucs03_zkgm

import (
	"strings"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	u256 "gno.land/p/onbloc/math/uint256"
	"gno.land/r/demo/defi/grc20reg"
)

// ibcDenomPrefix is the prefix of wrapped IBC voucher denoms.
const ibcDenomPrefix = "ibc/"

const (
	IBC_TOKEN   = iota // zkgm-issued voucher; custody is the proxy's voucher-ledger balance
	GRC20_TOKEN        // locally registered grc20; not supported by recovery
	NATIVE_COIN        // banker coin; custody is the proxy's banker balance
)

func isIBCTokenDenom(denom string) bool {
	return strings.HasPrefix(denom, ibcDenomPrefix)
}

func getTokenType(denom string) int {
	if isIBCTokenDenom(denom) {
		return IBC_TOKEN
	}

	if token := grc20reg.Get(denom); token != nil {
		return GRC20_TOKEN
	}

	return NATIVE_COIN
}

// amountInt64 narrows a ledger-precision uint256 to int64 (no scaling).
func amountInt64(amount *u256.Uint) (int64, error) {
	return z.ScaleDownToInt64(amount, 0)
}

// ledgerAmountOf narrows an origin-precision amount to ledger precision, via
// the voucher's ScaleExp when denom is a registered ibc voucher, or identity
// otherwise (native coin — mirrors v1's ledgerAmountOf).
func (v *ucs03ZkgmV2LockedRecovery) ledgerAmountOf(denom string, amount *u256.Uint) (int64, error) {
	if vou, ok := v.store.GetVoucher(denom); ok {
		return vou.ToLedgerAmount(amount)
	}

	return amountInt64(amount)
}

package ucs03_zkgm

import (
	"errors"
	"strings"
)

// Error messages, built via makeError at the call site.
const (
	errChannelBalanceUnderflow = "zkgm/channel_balance: underflow"

	errRecoveryUnsupportedTokenType = "zkgm/recovery: only native coin or ibc voucher escrow is supported"
	errRecoveryUnrecognizedKind     = "zkgm/recovery: only ESCROW-kind orders are supported"
	errInvalidRecipient             = "zkgm/recovery: recipient is not a valid address"
	errRecoveryZeroAmount           = "zkgm/recovery: amount must be positive"
	errBaseTokenRequired            = "zkgm/recovery: base token is required"
	errQuoteTokenRequired           = "zkgm/recovery: quote token is required"
	errVoucherNotFound              = "voucher not found"

	// errSpoofedRealm: rlm must be the current crossing frame, not a forged/stale token.
	errSpoofedRealm = "rlm does not match the current crossing frame"
)

func makeError(msgs ...string) error {
	return errors.New(strings.Join(msgs, ", "))
}

package ucs03_zkgm

import (
	"chain"
	"chain/banker"

	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

// sendNative releases amount of denom from the proxy escrow account to receiver.
func (v *ucs03ZkgmV2LockedRecovery) sendNative(_ int, rlm realm, denom string, receiver address, amount *u256.Uint) error {
	n, err := amountInt64(amount)
	if err != nil {
		return err
	}
	// rlm is the proxy's frame (interrealm borrow), so this draws from the proxy's own balance.
	b := banker.NewBanker(banker.BankerTypeRealmSend, rlm)
	b.SendCoins(rlm.Address(), receiver, chain.NewCoins(chain.NewCoin(denom, n)))
	zkgm.EmitNativeReleased(0, rlm, denom, receiver, n)

	return nil
}

package ucs03_zkgm

import (
	"chain"
	"strconv"

	types "gno.land/p/onbloc/ibc/union/types"
	u256 "gno.land/p/onbloc/math/uint256"
)

// AdminRecoveredLockedTokenEvent is this impl's own event (chain.Emit needs no
// proxy-side registration), recorded under this realm's pkgpath — distinct
// from the ZkgmNativeReleasedEvent/grc20 Transfer events releaseLockedToken also emits.
// origin_amount and ledger_amount are both emitted since Send's input unit
// (origin precision) differs from what actually moves (ledger precision) for
// scaled ibc vouchers — see adminRecoverLockedToken/ledgerAmountOf.
const AdminRecoveredLockedTokenEvent = "AdminRecoveredLockedToken"

func emitAdminRecoveredLockedTokenEvent(admin address, channelId types.ChannelId, denom string, recipient address, originAmount *u256.Uint, ledgerAmount int64) {
	chain.Emit(
		AdminRecoveredLockedTokenEvent,
		"admin", admin.String(),
		"channel_id", channelId.String(),
		"denom", denom,
		"recipient", recipient.String(),
		"origin_amount", originAmount.ToString(),
		"ledger_amount", strconv.FormatInt(ledgerAmount, 10),
	)
}

package ucs03_zkgm

import (
	types "gno.land/p/onbloc/ibc/union/types"
	tb "gno.land/p/onbloc/ibc/union/zkgm/tokenbucket"
	u256 "gno.land/p/onbloc/math/uint256"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

// getters.gno implements IAppGetter; results are snapshots, not mutable proxy-owned pointers.

// GetTokenBucket returns the rate-limit bucket configured for denom.
func (v *ucs03ZkgmV2LockedRecovery) GetTokenBucket(denom string) (*tb.TokenBucket, error) {
	bucket, ok := v.store.GetTokenBucket(denom)
	if !ok || bucket == nil {
		return nil, makeError(zkgm.ErrTokenBucketNotFound, denom)
	}

	return cloneTokenBucket(bucket), nil
}

// GetChannelBalanceV2 returns the escrow balance for the v2 channel-balance key.
func (v *ucs03ZkgmV2LockedRecovery) GetChannelBalanceV2(channelId types.ChannelId, path *u256.Uint, baseToken string, quoteToken []byte) (*u256.Uint, error) {
	balance, ok := v.store.GetChannelBalanceV2(ChannelBalanceKeyV2(channelId, path, []byte(baseToken), quoteToken))
	if !ok || balance == nil {
		return nil, makeError(zkgm.ErrChannelBalanceV2NotFound, channelId.String())
	}

	return balance.Clone(), nil
}

// GetLockedTokenAmount returns the terminally locked base-token amount for denom.
func (v *ucs03ZkgmV2LockedRecovery) GetLockedTokenAmount(denom string) (*u256.Uint, error) {
	total, ok := v.store.GetLockedTokenAmount(denom)
	if !ok || total == nil {
		return u256.Zero(), nil
	}

	return total.Clone(), nil
}

// GetVoucherList returns a page of up to count vouchers starting at offset. The
// error return is always nil; it exists only to match IAppGetter's convention.
func (v *ucs03ZkgmV2LockedRecovery) GetVoucherList(offset, count int) ([]zkgm.VoucherInfo, error) {
	return v.store.GetVoucherList(offset, count), nil
}

// GetVoucherSize returns the total number of registered vouchers (error always nil).
func (v *ucs03ZkgmV2LockedRecovery) GetVoucherSize() (int, error) {
	return v.store.GetVoucherSize(), nil
}

// GetVoucherInfo returns a snapshot of the single voucher registered for ibcDenom.
func (v *ucs03ZkgmV2LockedRecovery) GetVoucherInfo(ibcDenom string) (zkgm.VoucherInfo, error) {
	vou, ok := v.store.GetVoucher(ibcDenom)
	if !ok || vou == nil {
		return zkgm.NewVoucherInfo("", "", "", 0, 0, 0), makeError(errVoucherNotFound, ibcDenom)
	}

	return zkgm.NewVoucherInfo(
		ibcDenom,
		vou.Token().GetName(),
		vou.Token().GetSymbol(),
		vou.OriginDecimals(),
		uint8(vou.Token().GetDecimals()),
		vou.Token().TotalSupply(),
	), nil
}

func cloneTokenBucket(bucket *tb.TokenBucket) *tb.TokenBucket {
	return &tb.TokenBucket{
		Capacity:   bucket.Capacity.Clone(),
		Available:  bucket.Available.Clone(),
		RefillRate: bucket.RefillRate.Clone(),
		LastRefill: bucket.LastRefill.Clone(),
	}
}

package ucs03_zkgm

import (
	types "gno.land/p/onbloc/ibc/union/types"

	z "gno.land/p/onbloc/ibc/union/zkgm"
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

// ucs03ZkgmV2LockedRecovery is an emergency-only impl: everything except Send
// panics ("recovery impl: X not supported"). Send is repurposed as the
// admin-only escrow-release entrypoint; see its own comment.
type ucs03ZkgmV2LockedRecovery struct {
	store zkgm.IStore
}

var _ zkgm.IApp = &ucs03ZkgmV2LockedRecovery{}

// NewUCS03ZkgmV2LockedRecovery constructs a fresh recovery impl bound to the injected store.
func NewUCS03ZkgmV2LockedRecovery(store zkgm.IStore) zkgm.IApp {
	return &ucs03ZkgmV2LockedRecovery{store: store}
}

func notSupported(name string) string {
	return "recovery impl: " + name + " not supported"
}

func (v *ucs03ZkgmV2LockedRecovery) OnChannelOpenInit(_ int, rlm realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, relayer address) {
	panic(notSupported("OnChannelOpenInit"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnChannelOpenTry(_ int, rlm realm, connectionId types.ConnectionId, channelId types.ChannelId, version string, counterpartyVersion string, relayer address) {
	panic(notSupported("OnChannelOpenTry"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnChannelOpenAck(_ int, rlm realm, channelId types.ChannelId, counterpartyChannelId types.ChannelId, counterpartyVersion string, relayer address) {
	panic(notSupported("OnChannelOpenAck"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnChannelOpenConfirm(_ int, rlm realm, channelId types.ChannelId, relayer address) {
	panic(notSupported("OnChannelOpenConfirm"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnChannelCloseInit(_ int, rlm realm, channelId types.ChannelId, relayer address) {
	panic(notSupported("OnChannelCloseInit"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnChannelCloseConfirm(_ int, rlm realm, channelId types.ChannelId, relayer address) {
	panic(notSupported("OnChannelCloseConfirm"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnRecvPacket(_ int, rlm realm, packet types.Packet, relayer address, relayerMsg []byte) types.RecvPacketResult {
	panic(notSupported("OnRecvPacket"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnIntentRecvPacket(_ int, rlm realm, packet types.Packet, marketMaker address, marketMakerMsg []byte) types.RecvPacketResult {
	panic(notSupported("OnIntentRecvPacket"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnAcknowledgementPacket(_ int, rlm realm, packet types.Packet, acknowledgement []byte, relayer address) {
	panic(notSupported("OnAcknowledgementPacket"))
}

func (v *ucs03ZkgmV2LockedRecovery) OnTimeoutPacket(_ int, rlm realm, packet types.Packet, relayer address) {
	panic(notSupported("OnTimeoutPacket"))
}

func (v *ucs03ZkgmV2LockedRecovery) VoucherApprove(_ int, rlm realm, ibcDenom string, spender address, amount int64) error {
	panic(notSupported("VoucherApprove"))
}

func (v *ucs03ZkgmV2LockedRecovery) VoucherTransfer(_ int, rlm realm, ibcDenom string, to address, amount int64) error {
	panic(notSupported("VoucherTransfer"))
}

// Send is repurposed as the admin-only recovery entrypoint, reachable through
// the proxy's existing SendRaw (no proxy-side change needed). Operand is a
// standard ABI-encoded TokenOrderV2:
//   - Kind: must be TOKEN_ORDER_KIND_ESCROW — the only kind an active escrow can be released as
//   - BaseToken/QuoteToken: the channelBalanceV2 key to release (path always zero)
//   - BaseAmount: origin-token precision, same units as an ordinary Send —
//     ledgerAmountOf downscales via the voucher's ScaleExp for an ibc denom,
//     or passes through unchanged for native coin (origin == ledger there)
//   - Receiver: recipient address string; must pass address.IsValid()
//   - Sender, QuoteAmount, Metadata are ignored
//
// timeoutTimestamp and salt are unused; they exist only to satisfy IAppTransfer.
func (v *ucs03ZkgmV2LockedRecovery) Send(_ int, rlm realm, channelId types.ChannelId, timeoutTimestamp types.Timestamp, salt [32]byte, instruction z.Instruction) types.Packet {
	assertIsRlmCurrent(0, rlm)

	// Reject anything not built with the expected version/opcode instead of decoding loosely.
	if instruction.Version != z.INSTR_VERSION_2 || instruction.Opcode != z.OP_TOKEN_ORDER {
		panic(notSupported("Send: unrecognized version/opcode"))
	}

	order, err := z.DecodeTokenOrderV2(instruction.Operand)
	if err != nil {
		panic(err)
	}

	// A runbook mistake (e.g. reusing an INITIALIZE/UNESCROW operand) must not
	// be reinterpreted as a recovery request.
	if order.Kind != z.TOKEN_ORDER_KIND_ESCROW {
		panic(makeError(errRecoveryUnrecognizedKind))
	}

	v.adminRecoverLockedToken(0, rlm, channelId, order.BaseToken, order.QuoteToken, order.BaseAmount, address(order.Receiver))

	return types.Packet{}
}

package ucs03_zkgm

import (
	zkgm "gno.land/r/onbloc/ibc/union/apps/ucs03_zkgm"
)

func init(cur realm) {
	zkgm.RegisterImpl(cross(cur), func(s zkgm.IStore) zkgm.IApp {
		return NewUCS03ZkgmV2LockedRecovery(s)
	})
}

package ucs03_zkgm

import (
	"gno.land/p/onbloc/access/manager"
	types "gno.land/p/onbloc/ibc/union/types"

	u256 "gno.land/p/onbloc/math/uint256"
	"gno.land/r/onbloc/ibc/union/access"
)

// selectorAdminRecoverLockedToken gates Send to admin. Defined here, not in the
// already-deployed access.gno — an unconfigured selector defaults to AdminRole
// (manager.GetTargetFunctionRole), so no proxy-side change is needed.
const selectorAdminRecoverLockedToken manager.Selector = "v2_locked_recovery/admin_recover_locked_token"

// adminRecoverLockedToken releases originAmount (origin-token precision, same
// units as an ordinary Send — see ledgerAmountOf) of the (channelId, path=0,
// baseToken, quoteToken) escrow to recipient. decreaseChannelBalanceV2 is the
// fund-safety check; failures here panic (not return) so the whole tx reverts
// atomically — no hand-written rollback. Native coin and ibc/ vouchers only;
// recipient must pass address.IsValid() so a malformed/non-Gno recipient
// can't receive funds nobody controls.
//
// Out of scope on purpose: store.lockedTokenAmounts (see burnEscrowedV2 in
// v1/token_order.gno). The deployed IStore only exposes an additive
// AddLockedTokenAmount, no decrement, so no impl can recover it without a
// proxy-side IStore change — moot anyway since no market maker is in use.
func (v *ucs03ZkgmV2LockedRecovery) adminRecoverLockedToken(_ int, rlm realm, channelId types.ChannelId, baseToken, quoteToken []byte, originAmount *u256.Uint, recipient address) {
	access.AssertCanCall(0, rlm, selectorAdminRecoverLockedToken)

	if originAmount.IsZero() {
		panic(makeError(errRecoveryZeroAmount))
	}

	if !recipient.IsValid() {
		panic(makeError(errInvalidRecipient))
	}

	if len(baseToken) == 0 {
		panic(makeError(errBaseTokenRequired))
	}

	if len(quoteToken) == 0 {
		panic(makeError(errQuoteTokenRequired))
	}

	path := u256.Zero()
	denom := string(baseToken)

	tokenType := getTokenType(denom)
	if tokenType != NATIVE_COIN && tokenType != IBC_TOKEN {
		panic(makeError(errRecoveryUnsupportedTokenType))
	}

	amount, err := v.ledgerAmountOf(denom, originAmount)
	if err != nil {
		panic(err)
	}

	if err := v.decreaseChannelBalanceV2(0, rlm, channelId, path, baseToken, quoteToken, amount); err != nil {
		panic(err)
	}

	if err := v.releaseLockedToken(0, rlm, tokenType, denom, recipient, amount); err != nil {
		panic(err)
	}

	emitAdminRecoveredLockedTokenEvent(rlm.Previous().Address(), channelId, denom, recipient, originAmount, amount)
}

// releaseLockedToken moves amount (channelBalanceV2/ledger precision) of denom
// to recipient. Uses the voucher's raw ledger balance directly rather than the
// *Scaled helpers, which expect origin precision and would downscale again
// (e.g. an 18-decimal origin token on a 6-decimal ledger).
func (v *ucs03ZkgmV2LockedRecovery) releaseLockedToken(_ int, rlm realm, tokenType int, denom string, recipient address, amount int64) error {
	if tokenType == IBC_TOKEN {
		vou, ok := v.store.GetVoucher(denom)
		if !ok {
			return makeError(errVoucherNotFound, denom)
		}

		return vou.Ledger().Transfer(rlm.Address(), recipient, amount)
	}

	return v.sendNative(0, rlm, denom, recipient, u256.NewUint(uint64(amount)))
}

